import React, { useState, useRef } from 'react';
import { Upload, Image as ImageIcon, X, Sparkles, RefreshCw, Check } from 'lucide-react';

/**
 * Optimizes an uploaded image file by drawing it onto a temporary canvas
 * and converting it to a compressed JPEG/WebP data URL to keep localStorage fast.
 */
const optimizeImageFile = (file, maxWidth = 1400, quality = 0.85) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (readerEvent) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        if (!ctx) {
          resolve(readerEvent.target?.result);
          return;
        }

        ctx.drawImage(img, 0, 0, width, height);
        const optimizedDataUrl = canvas.toDataURL('image/jpeg', quality);
        resolve(optimizedDataUrl);
      };
      img.onerror = () => resolve(readerEvent.target?.result);
      img.src = readerEvent.target?.result;
    };
    reader.onerror = (err) => reject(err);
    reader.readAsDataURL(file);
  });
};

