/**
 * APEX ATELIER - Supercar Acoustic Synthesizer (Web Audio API)
 * Generates dynamic high-fidelity V12 / Electric Hypercar engine acoustics without external audio assets.
 */

class AudioEngine {
  constructor() {
    this.ctx = null;
    this.isMuted = true;
    this.idleOsc = null;
    this.subOsc = null;
    this.filter = null;
    this.gainNode = null;
    this.revGain = null;
    this.isInitialized = false;
  }

  init() {
    if (this.isInitialized) return;
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AudioCtx();

      // Master Gain
      this.gainNode = this.ctx.createGain();
      this.gainNode.gain.setValueAtTime(0, this.ctx.currentTime);
      this.gainNode.connect(this.ctx.destination);

      // Lowpass Filter for low engine rumble
      this.filter = this.ctx.createBiquadFilter();
      this.filter.type = 'lowpass';
      this.filter.frequency.setValueAtTime(160, this.ctx.currentTime);
      this.filter.Q.setValueAtTime(4, this.ctx.currentTime);
      this.filter.connect(this.gainNode);

      // Engine fundamental idle rumble
      this.idleOsc = this.ctx.createOscillator();
      this.idleOsc.type = 'sawtooth';
      this.idleOsc.frequency.setValueAtTime(48, this.ctx.currentTime); // 48Hz base idle

      // Sub bass body
      this.subOsc = this.ctx.createOscillator();
      this.subOsc.type = 'triangle';
      this.subOsc.frequency.setValueAtTime(24, this.ctx.currentTime);

      this.idleOsc.connect(this.filter);
      this.subOsc.connect(this.filter);

      this.idleOsc.start();
      this.subOsc.start();

      this.isInitialized = true;
    } catch (e) {
      console.warn('Web Audio API not supported or blocked by browser policy:', e);
    }
  }

  toggleSound() {
    if (!this.isInitialized) this.init();
    if (!this.ctx) return false;

    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }

    this.isMuted = !this.isMuted;
    const targetGain = this.isMuted ? 0 : 0.08;
    this.gainNode.gain.cancelScheduledValues(this.ctx.currentTime);
    this.gainNode.gain.linearRampToValueAtTime(targetGain, this.ctx.currentTime + 0.3);

    return !this.isMuted;
  }

  playRev(duration = 1.2, intensity = 1.0) {
    if (!this.isInitialized) this.init();
    if (!this.ctx || this.isMuted) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const revFilter = this.ctx.createBiquadFilter();

    osc.type = 'sawtooth';
    revFilter.type = 'bandpass';
    revFilter.frequency.setValueAtTime(320, now);
    revFilter.Q.setValueAtTime(3.5, now);

    // Dynamic pitch curve mimicking a sequential downshift & throttle blip
    osc.frequency.setValueAtTime(65, now);
    osc.frequency.exponentialRampToValueAtTime(380 * intensity, now + 0.35);
    osc.frequency.exponentialRampToValueAtTime(95, now + duration);

    revFilter.frequency.setValueAtTime(300, now);
    revFilter.frequency.exponentialRampToValueAtTime(1400 * intensity, now + 0.35);
    revFilter.frequency.exponentialRampToValueAtTime(280, now + duration);

    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.18 * intensity, now + 0.1);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);

    osc.connect(revFilter);
    revFilter.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + duration + 0.05);
  }

  playClick() {
    if (!this.ctx || this.isMuted) return;
    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      osc.frequency.exponentialRampToValueAtTime(200, now + 0.04);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.04);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(now);
      osc.stop(now + 0.05);
    } catch (e) {}
  }
}

