export default function HeroSequence({ onProgressUpdate, onLoaded, onOpenBooking }) {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const frameIndexRef = useRef(0);
  const imagesRef = useRef([]);
  const rAFIdRef = useRef(null);
  const [activeHotspot, setActiveHotspot] = useState(null);
  const [scrollPhase, setScrollPhase] = useState(0); // 0: Intro, 1: Aero, 2: Track, 3: CTA

  const TOTAL_FRAMES = 600;

  // 1. Decoupled rAF Render Loop (reads frameIndexRef at monitor vsync)
  const renderFrame = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const img = imagesRef.current[frameIndexRef.current | 0];
    if (img && (img.complete || img instanceof ImageBitmap)) {
      const cw = canvas.width;
      const ch = canvas.height;
      const iw = img.width || 1920;
      const ih = img.height || 1080;

      // Object fit cover calculation with integer coordinates
      const scale = Math.max(cw / iw, ch / ih);
      const sw = (iw * scale) | 0;
      const sh = (ih * scale) | 0;
      const sx = ((cw - sw) / 2) | 0;
      const sy = ((ch - sh) / 2) | 0;

      ctx.drawImage(img, 0, 0, iw, ih, sx, sy, sw, sh);
    }

    rAFIdRef.current = requestAnimationFrame(renderFrame);
  }, []);

  // 2. Pre-cache 600 Frames with GPU Off-Thread Decoding
  useEffect(() => {
    let isCancelled = false;
    let loadedCount = 0;
    const images = new Array(TOTAL_FRAMES);

    // Canvas size setup
    const handleResize = () => {
      if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth * window.devicePixelRatio;
        canvasRef.current.height = window.innerHeight * window.devicePixelRatio;
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);

    const batchSize = 12;
    let currentBatch = 0;

    const loadNextBatch = async () => {
      if (isCancelled || currentBatch * batchSize >= TOTAL_FRAMES) {
        if (loadedCount >= TOTAL_FRAMES * 0.95 && !isCancelled) {
          onLoaded?.();
        }
        return;
      }

      const promises = [];
      for (let i = 0; i < batchSize; i++) {
        const frameIdx = currentBatch * batchSize + i;
        if (frameIdx >= TOTAL_FRAMES) break;

        const frameNum = String(frameIdx + 1).padStart(3, '0');
        // Primary path from skill extractor
        const src = `/cabinet_frames_600fps/frame_${frameNum}.jpg`;

        const p = fetch(src)
          .then(res => {
            if (!res.ok) throw new Error('Fetch failed');
            return res.blob();
          })
          .then(blob => window.createImageBitmap ? createImageBitmap(blob) : null)
          .then(bitmap => {
            if (isCancelled) return;
            if (bitmap) {
              images[frameIdx] = bitmap;
            } else {
              // Fallback for browsers without createImageBitmap
              const img = new Image();
              img.src = src;
              images[frameIdx] = img;
            }
            loadedCount++;
            onProgressUpdate?.((loadedCount / TOTAL_FRAMES) * 100);
          })
          .catch(() => {
            // Fallback direct Image element
            const img = new Image();
            img.src = src;
            images[frameIdx] = img;
            loadedCount++;
            onProgressUpdate?.((loadedCount / TOTAL_FRAMES) * 100);
          });

        promises.push(p);
      }

      await Promise.all(promises);
      currentBatch++;
      loadNextBatch();
    };

