      {/* Atmospheric Vignette & Tint in Black Green + Ruby */}
      <div className="absolute inset-0 bg-gradient-to-t from-canvas via-transparent to-canvas/70 pointer-events-none z-10" />
      <div className="absolute inset-0 bg-gradient-to-r from-canvas/60 via-transparent to-canvas/60 pointer-events-none z-10" />
      <div className="absolute inset-0 hud-scanline opacity-15 pointer-events-none z-10" />

      {/* Telemetry Corner HUD Elements */}
      <div className="absolute top-24 left-6 z-20 hidden md:flex flex-col space-y-1 font-mono text-[11px] text-brand-text-muted">
        <div className="flex items-center space-x-2">
