const fs = require('fs');
const path = require('path');

function stripBomInDir(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'public') continue;
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      stripBomInDir(fullPath);
    } else if (entry.name.endsWith('.json') || entry.name.endsWith('.js') || entry.name.endsWith('.jsx') || entry.name.endsWith('.css') || entry.name.endsWith('.html') || entry.name.endsWith('.md')) {
      let content = fs.readFileSync(fullPath, 'utf8');
      if (content.charCodeAt(0) === 0xFEFF) {
        content = content.slice(1);
        fs.writeFileSync(fullPath, content, 'utf8');
        console.log('Stripped BOM from:', fullPath);
      }
    }
  }
}

stripBomInDir('.');
console.log('BOM cleanup complete.');
")

