            setScrollPhase(0);
          } else if (rawProgress >= 0.22 && rawProgress < 0.52) {
            setScrollPhase(1);
          } else if (rawProgress >= 0.52 && rawProgress < 0.78) {
            setScrollPhase(2);
          } else {
            setScrollPhase(3);
          }
        }
      });
    }, containerRef);

    return () => ctx.revert();
  }, []);

