gsap.registerPlugin(ScrollTrigger);

export default function HeroSequence({ onOpenTestDriveModal, onExploreFleet }) {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const frameIndexRef = useRef(0);
  const imagesRef = useRef([]);
  const animFrameIdRef = useRef(null);
  const scrollTriggerInstanceRef = useRef(null);

  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoaded, setIsLoaded] = useState(false);
  const [currentStage, setCurrentStage] = useState(0);
  const [liveGForce, setLiveGForce] = useState(1.02);
  const [liveRpm, setLiveRpm] = useState(2400);

  // 1. Off-Thread GPU Pre-Decoding & Asset Ingestion
  useEffect(() => {
    let isCancelled = false;
    const totalFrames = frameList.length;
    let loadedCount = 0;
    const batchSize = 16;

    const loadBatch = async (startIndex) => {
      if (isCancelled || startIndex >= totalFrames) return;
      const endIndex = Math.min(startIndex + batchSize, totalFrames);
      const promises = [];

      for (let i = startIndex; i < endIndex; i++) {
        const frameName = frameList[i];
        const src = `/cabinet_frames_600fps/${frameName}`;

        const p = fetch(src)
          .then((res) => {
            if (!res.ok) throw new Error(`Frame fetch failed: ${src}`);
            return res.blob();
          })
          .then((blob) => createImageBitmap(blob))
          .then((bitmap) => {
            if (!isCancelled) {
              imagesRef.current[i] = bitmap;
              loadedCount++;
              setLoadingProgress(Math.floor((loadedCount / totalFrames) * 100));
            }
          })
          .catch((err) => {
            // Fallback for non-bitmap environments
            return new Promise((resolve) => {
              const img = new Image();
              img.src = src;
              img.onload = () => {
                if (!isCancelled) {
                  imagesRef.current[i] = img;
                  loadedCount++;
                  setLoadingProgress(Math.floor((loadedCount / totalFrames) * 100));
                }
                resolve();
              };
              img.onerror = () => resolve();
            });
          });

        promises.push(p);
      }

      await Promise.all(promises);
      if (!isCancelled && endIndex < totalFrames) {
        loadBatch(endIndex);
      } else if (!isCancelled && loadedCount >= totalFrames * 0.9) {
        setIsLoaded(true);
      }
    };

    loadBatch(0);

    return () => {
      isCancelled = true;
    };
  }, []);

  // 2. Decoupled rAF Render Loop & Canvas Initialization
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    let lastDrawnIndex = -1;

    const render = () => {
      const targetIndex = Math.min(
        Math.max(0, frameIndexRef.current | 0),
        frameList.length - 1
      );

      const img = imagesRef.current[targetIndex] || imagesRef.current[0];

      if (img && targetIndex !== lastDrawnIndex) {
        const cw = canvas.width;
        const ch = canvas.height;
        const iw = img.width || 1920;
        const ih = img.height || 1080;

        // Cover fit with integer floor coordinates to prevent anti-aliasing shimmer
        const hRatio = cw / iw;
        const vRatio = ch / ih;
        const ratio = Math.max(hRatio, vRatio);

        const sw = (iw * ratio) | 0;
        const sh = (ih * ratio) | 0;
        const sx = ((cw - sw) / 2) | 0;
        const sy = ((ch - sh) / 2) | 0;

        ctx.fillStyle = '#000F08';
        ctx.fillRect(0, 0, cw, ch);
        ctx.drawImage(img, sx, sy, sw, sh);

        lastDrawnIndex = targetIndex;
      }

      animFrameIdRef.current = requestAnimationFrame(render);
    };

    const handleResize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = (window.innerWidth * dpr) | 0;
      canvas.height = (window.innerHeight * dpr) | 0;
      lastDrawnIndex = -1; // Force repaint
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    animFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      window.removeEventListener('resize', handleResize);
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
      }
    };
