          }

          // Dynamic telemetry simulation
          const velocityFactor = Math.abs(self.getVelocity() / 1000);
          const calculatedRpm = Math.min(9200, Math.floor(2200 + progress * 5000 + velocityFactor * 1200));
          const calculatedG = (1.0 + progress * 0.75 + velocityFactor * 0.15).toFixed(2);
          setLiveRpm(calculatedRpm);
          setLiveGForce(calculatedG);
        },
      },
    });

    scrollTriggerInstanceRef.current = scrollAnim.scrollTrigger;

