    setTestDriveModalOpen(true);
  };

  const handleCloseModal = () => {
    setTestDriveModalOpen(false);
  };

  return (
    <div className=\"min-h-screen bg-[#000F08] text-[#F5FAF7] relative selection:bg-[#FB3640] selection:text-white antialiased font-sans\">
